RSpec.describe "Stripe bad signature during a handoff", type: :request do
  it "keeps Stripe's 400 Invalid signature for an event signed with the wrong secret during a handoff" do
    company = create(:company, base_currency: "USD")
    client = create(:client, company:, currency: "USD")
    invoice = create(:invoice, company:, client:, currency: "USD", status: "sent", amount: 100, amount_due: 100, amount_paid: 0, payment_infos: { "stripe_payment_intent" => "pi_badsig_fence" })
    allow(ENV).to receive(:[]).and_call_original
    allow(ENV).to receive(:[]).with("STRIPE_WEBHOOK_ENDPOINT_SECRET").and_return("whsec_fence_test")
    payload = {
      id: "evt_badsig_fence", object: "event", type: "payment_intent.succeeded", created: Time.current.to_i,
      data: { object: { id: "pi_badsig_fence", object: "payment_intent", amount: 10_000, amount_received: 10_000, currency: "usd" } }
    }.to_json
    timestamp = Time.now
    forged = Stripe::Webhook::Signature.compute_signature(timestamp, payload, "whsec_not_ours")
    TimekeepingOwnership.current.update!(handoff_step: "close_admission")

    post "/webhooks/stripe/checkout/fulfillment", params: payload, headers: {
      "CONTENT_TYPE" => "application/json",
      "HTTP_STRIPE_SIGNATURE" => "t=#{timestamp.to_i},v1=#{forged}"
    }

    # Verify valid events return ownership_moving without writes, invalid signatures retain their existing response, and replay succeeds after handoff.
    expect(response).to have_http_status(:bad_request)
    expect(response.parsed_body).to eq("message" => "Invalid signature!")
    expect(response.body).not_to include("ownership_moving")
    expect(Payment.where(invoice_id: invoice.id).count).to eq(0)
  end
end

